import{_ as n,C as d,o as e,c as i,a2 as a,b as l,w as r,a as s,E as h,a3 as g}from"./chunks/framework.l6sz0Vgx.js";const _=JSON.parse('{"title":"从GoF到Agent模式","description":"GoF管确定性协作，Agent模式管运行时决策 — 分层与选型","frontmatter":{"title":"从GoF到Agent模式","description":"GoF管确定性协作，Agent模式管运行时决策 — 分层与选型"},"headers":[],"relativePath":"posts/gof-agent.md","filePath":"posts/gof-agent.md","lastUpdated":1791738670000}'),c={name:"posts/gof-agent.md"};function A(u,t,p,f,E,b){const o=d("Mermaid");return e(),i("div",null,[t[1]||(t[1]=a('<h1 id="从gof到agent模式" tabindex="-1">从GoF到Agent模式 <a class="header-anchor" href="#从gof到agent模式" aria-label="Permalink to &quot;从GoF到Agent模式&quot;">​</a></h1><p><strong>摘要：</strong> 先一句话定位 GoF，再用 L0–L5 分层讲清 Agent 模式住在哪层、和传统做法像在哪不像在哪，最后用选型表和检查单收口。与《Agent手册》分工：手册讲系统由什么组成，本篇讲模式怎么演进。</p><p><strong>怎么读：</strong> §1 一句话定位 GoF → §2 分层（核心）→ §3–§5 三组（照抄/改造/全新）→ §6 选型检查单。</p><blockquote><p>GoF 管确定性协作，Agent 模式管运行时决策。</p></blockquote><p>做过后端的都熟：23 种 GoF + 微服务的熔断、管道、分流，解决的是&quot;对象怎么写才稳&quot;。Agent 把调用者换成了大模型——它会自己定下一步、自己调工具、自己改答案。于是多了三种传统代码里没有的失败：幻觉调不存在的工具、无限反思改个没完、token/钱烧穿。</p><p>本文不做一一对照，只讲清一件事：Agent 模式住在哪些层，每层和传统做法的逻辑关系是什么。</p><h2 id="_1-gof-一句话定位" tabindex="-1">1. GoF 一句话定位 <a class="header-anchor" href="#_1-gof-一句话定位" aria-label="Permalink to &quot;1. GoF 一句话定位&quot;">​</a></h2><p><strong>一句话：GoF 23 = 创建管 new、结构管包、行为管调，解决&quot;对象怎么写才稳&quot;——后文只借它的逻辑，不再展开。</strong></p><ul><li>后端最常用的七个（单例/工厂/代理/策略/观察者/模板方法/责任链）在《Java/Python笔记》§4 已有落点（Boot Bean、AOP、事件机制、拦截器链），不再重复。</li><li>OO 五原则（单一职责、开闭、里氏替换、接口隔离、依赖倒置）是方向，模式是招式——这句话在两边通用。</li></ul><h2 id="_2-分层-先分层-逻辑自清" tabindex="-1">2. 分层：先分层，逻辑自清 <a class="header-anchor" href="#_2-分层-先分层-逻辑自清" aria-label="Permalink to &quot;2. 分层：先分层，逻辑自清&quot;">​</a></h2><p><strong>一句话：GoF 住在代码层，Agent 模式横跨五层——看清模式住哪层，像不像自有分晓。</strong></p><table tabindex="0"><thead><tr><th>层</th><th>解决什么</th><th>含哪些 Agent 模式</th><th>和传统的关系</th></tr></thead><tbody><tr><td>L0 代码实现层</td><td>单个类/函数怎么写</td><td>Tool 对象创建、Memory 存取、事件分发内部实现</td><td>直接复用：Factory 建 Tool、Singleton 管 Session、Observer 推事件</td></tr><tr><td>L1-L2 架构/集成层</td><td>系统怎么连、流程怎么走</td><td>提示链、路由、并行、Orchestrator、MCP/RAG、A2A、目标监控、异常恢复</td><td>逻辑相通：管道、策略、分治、中介、熔断、Saga，换的是调用者</td></tr><tr><td>L3 思考认知层</td><td>Agent 怎么想</td><td>推理（ReAct/CoT/ToT）、规划、反思/Evaluator、学习适应、探索发现、优先级排序</td><td><strong>无传统等价物</strong>，这是 Agent 增量</td></tr><tr><td>L4-L5 协作治理层</td><td>多智能体 + 人 + 运维怎么管</td><td>多智能体协作、HITL、Guardrails、评估监控、资源优化</td><td>逻辑相通：Actor、Proxy、Observer、SRE，载荷换成自然语言</td></tr></tbody></table><ul><li>结论先行：约 1/3 直接复用，1/3 要改造；真正的增量是 L3 思考层（ReAct、规划、反思——机器自己想）。多智能体归协作层，逻辑沿用微服务，新的是自然语言载荷。</li><li>多智能体放协作层不放 L3：单个 Agent 的想是 L3，多个 Agent 怎么商量（debate/vote/handoff）是协作问题；反思是单体自省，多智能体是群体商量，分开读者更清楚。</li></ul><h2 id="_3-能直接抄的三组" tabindex="-1">3. 能直接抄的三组 <a class="header-anchor" href="#_3-能直接抄的三组" aria-label="Permalink to &quot;3. 能直接抄的三组&quot;">​</a></h2><p><strong>一句话：调用者从代码换成模型，但结构不变——照抄，多的只是一层&quot;防模型犯错&quot;的 gate。</strong></p><h3 id="工具使用-就是-adapter-但接口写给模型看" tabindex="-1">工具使用：就是 Adapter，但接口写给模型看 <a class="header-anchor" href="#工具使用-就是-adapter-但接口写给模型看" aria-label="Permalink to &quot;工具使用：就是 Adapter，但接口写给模型看&quot;">​</a></h3><p>传统 Adapter 把外部 API 包成内部接口，Agent 一样，只是调用者从代码变成了 LLM（Anthropic 称之为 ACI，对标 HCI）。标准六步：定义工具 → 模型决策 → 生成 JSON → 框架执行 → 回 observation → 再推理。写好三条：描述写给实习生看（含边界 + 示例）；参数显式、幂等、超时、沙盒；模型内能算的别调。</p><h3 id="提示链-就是管道-但每段都会幻觉" tabindex="-1">提示链：就是管道，但每段都会幻觉 <a class="header-anchor" href="#提示链-就是管道-但每段都会幻觉" aria-label="Permalink to &quot;提示链：就是管道，但每段都会幻觉&quot;">​</a></h3><p>大 prompt 三病：context drift、指令忽略、错误传播。拆成大纲 → 正文 → 校对，每步只做一件事，就是管道过滤器 + 模板方法。多的一层是 gate：每步后用代码判格式/长度/关键词，不过就停或重试，不让错往下流，全链打 trace-id。</p><h3 id="路由-guardrails-策略-代理-直接复用" tabindex="-1">路由 + Guardrails：策略 + 代理，直接复用 <a class="header-anchor" href="#路由-guardrails-策略-代理-直接复用" aria-label="Permalink to &quot;路由 + Guardrails：策略 + 代理，直接复用&quot;">​</a></h3><p>路由即 Strategy：先分诊再进专用 prompt/工具/模型，难的走大模型、易的走小模型，留 default 兜底（分类器本身会分错）。Guardrails 即保护代理 + 熔断：input / tool-call / tool-response / output 四点拦截，只检输出是典型反模式。生产三板斧：最大步数/钱上限、HITL 低置信转人工、trajectory 回放做 eval。</p><h2 id="_4-要改造的两组" tabindex="-1">4. 要改造的两组 <a class="header-anchor" href="#_4-要改造的两组" aria-label="Permalink to &quot;4. 要改造的两组&quot;">​</a></h2><p><strong>一句话：结构照抄，终止条件和任务形状变了——改造点全在&quot;什么时候停&quot;和&quot;任务何时才定&quot;。</strong></p><h3 id="反思-装饰器-备忘录-但终止条件是自然语言" tabindex="-1">反思：装饰器 + 备忘录，但终止条件是自然语言 <a class="header-anchor" href="#反思-装饰器-备忘录-但终止条件是自然语言" aria-label="Permalink to &quot;反思：装饰器 + 备忘录，但终止条件是自然语言&quot;">​</a></h3><p>生成者写一版，批判者照标准改一版（HumanEval 80%→91% 就靠这多看一眼）。像装饰器包增强，像备忘录存中间稿。不像的是改到什么时候停代码说不清：必须硬 cap 2–3 轮，且标准可验证（单测过、名单命中、格式器过）；先跑外部校验再让 LLM 改，只存 diff 省 token；无标准答案的创意写作别用。</p><h3 id="并行-orchestrator-分治-中介-但任务运行时才定" tabindex="-1">并行 + Orchestrator：分治 + 中介，但任务运行时才定 <a class="header-anchor" href="#并行-orchestrator-分治-中介-但任务运行时才定" aria-label="Permalink to &quot;并行 + Orchestrator：分治 + 中介，但任务运行时才定&quot;">​</a></h3><p>分治、投票聚合就是 Fork-Join 和 N-Version，差异最小。Orchestrator 是动态版：中央 LLM 看输入现拆活、分给 worker、再聚合，像 Mediator + Supervisor。写好：worker 输入输出定 schema，Supervisor 只分发不干活，并发加聚合超时，全轨迹 logging 否则挂了查不清。</p><h2 id="_5-l3-增量与多智能体" tabindex="-1">5. L3 增量与多智能体 <a class="header-anchor" href="#_5-l3-增量与多智能体" aria-label="Permalink to &quot;5. L3 增量与多智能体&quot;">​</a></h2><p><strong>一句话：ReAct 是运行时解释执行，规划是粗版 ReAct——L3 两式没有传统祖先；多智能体有逻辑祖先（微服务），新的是自然语言载荷。</strong></p><h3 id="react-规划" tabindex="-1">ReAct + 规划 <a class="header-anchor" href="#react-规划" aria-label="Permalink to &quot;ReAct + 规划&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>机制</th><th>适用</th><th>代价</th></tr></thead><tbody><tr><td>ReAct</td><td>思考→行动→观察交错（Yao 2022）</td><td>开放任务、工具多</td><td>步数多、易漂移</td></tr><tr><td>Reflexion</td><td>失败后自然语言复盘入记忆</td><td>可试错、有明确判分</td><td>需好评估器</td></tr><tr><td>Plan-and-Execute</td><td>先出计划再逐步执行、偏差重规划</td><td>长任务、步骤可列</td><td>规划错全错</td></tr></tbody></table><ul><li>生产配方：大计划粗分 + 每步内小 ReAct + 步步 grounding；流程固定的老实用提示链，别为智能而规划。</li><li>必须 Bounded：最大步/次/时三限，计划先打印给人看，失败回退上一步。状态机转移是写死的，ReAct 下一步是模型定的——这就是无祖先的原因。</li></ul><h3 id="多智能体-像微服务-但通信是自然语言" tabindex="-1">多智能体：像微服务，但通信是自然语言 <a class="header-anchor" href="#多智能体-像微服务-但通信是自然语言" aria-label="Permalink to &quot;多智能体：像微服务，但通信是自然语言&quot;">​</a></h3><p>单 context 装不下多角色才拆：研究员 / coder / 评审各一 agent。拓扑三选一：Chain 顺序、Star 集中、Mesh 对等（Microsoft 称 Sequential / Concurrent / GroupChat / Handoff / Magentic）。像微服务分工，不像的是线上传自然语言，会 drift、会互甩锅。先单 agent 顶，顶不住再拆——Over-Agentification 是头号反模式。Handoff 协议写死，A2A/MCP 互通，Supervisor 别下场干活。</p><h3 id="记忆与工具-三层-网关" tabindex="-1">记忆与工具：三层 + 网关 <a class="header-anchor" href="#记忆与工具-三层-网关" aria-label="Permalink to &quot;记忆与工具：三层 + 网关&quot;">​</a></h3><p>记忆分三层：当轮上下文（快、贵）→ 检索库（经验/文档按需取）→ 权重（慢、稳），热数据上浮、冷数据下沉。Agentic RAG 把检索本身放进循环（改写查询 → 检索 → 自评 → 再检索）。工具走网关：鉴权、限流、审计、幂等收一处，MCP 即标准化后的网关协议。评估器与验证器是同一个东西——验证器质量是所有循环的天花板（见《RSI 笔记》§1）。</p><h2 id="_6-选型与上线检查单" tabindex="-1">6. 选型与上线检查单 <a class="header-anchor" href="#_6-选型与上线检查单" aria-label="Permalink to &quot;6. 选型与上线检查单&quot;">​</a></h2><p><strong>一句话：按任务形状查表，默认从左往右试；按失败加模式，别按想象加。</strong></p>',38)),(e(),l(g,null,{default:r(()=>[h(o,{id:"mermaid-275",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Q%5B%22%E4%BB%BB%E5%8A%A1%E7%A1%AE%E5%AE%9A%E5%90%97%22%5D%20--%20%22%E7%A1%AE%E5%AE%9A%22%20--%3E%20W%5B%22%E5%B7%A5%E4%BD%9C%E6%B5%81%3Cbr%2F%3E%E9%93%BE%E5%BC%8F%E8%B7%AF%E7%94%B1%E5%B9%B6%E8%A1%8C%22%5D%0A%20%20%20%20Q%20--%20%22%E4%B8%8D%E7%A1%AE%E5%AE%9A%22%20--%3E%20A%5B%22%E8%87%AA%E4%B8%BB%E5%BE%AA%E7%8E%AF%3Cbr%2F%3EReAct%E7%B1%BB%22%5D%0A%20%20%20%20A%20--%20%22%E5%A4%9A%E6%8A%80%E8%83%BD%22%20--%3E%20M%5B%22%E5%A4%9A%E6%99%BA%E8%83%BD%E4%BD%93%3Cbr%2F%3E%E4%B8%BB%E7%AE%A1%E5%BC%8F%22%5D%0A%20%20%20%20W%20--%20%22%E8%B4%A8%E9%87%8F%E4%B8%8D%E5%A4%9F%22%20--%3E%20E%5B%22%E8%AF%84%E4%BC%B0%E4%BC%98%E5%8C%96%E7%8E%AF%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<table tabindex="0"><thead><tr><th>任务形状</th><th>首选</th><th>不够再加</th></tr></thead><tbody><tr><td>固定多步</td><td>链式</td><td>中间加校验门</td></tr><tr><td>先分类后处理</td><td>路由</td><td>错分加人工复核</td></tr><tr><td>独立子任务多</td><td>并行化</td><td>投票聚合</td></tr><tr><td>拆法事先不知</td><td>编排-工人</td><td>尾挂评估环</td></tr><tr><td>开放探索</td><td>ReAct</td><td>失败加 Reflexion</td></tr><tr><td>长计划任务</td><td>Plan-and-Execute</td><td>偏差重规划</td></tr><tr><td>多技能协作</td><td>主管-工人</td><td>正确性不够上辩论</td></tr></tbody></table><ul><li>加料顺序：单调用 + 工具 → 验证挂了加反思 → 步骤不定加规划 → 角色装不下才上多智能体 → 全程挂 Bounded + Guardrail + Logging。</li><li><strong>上线五问：</strong> ACI 文档实习生能看懂吗？最大步数钱上限有吗？四点拦截做了吗？低置信转人工了吗？20 条黄金用例能回放吗？全 yes 即可发。</li></ul><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>Anthropic《Building Effective Agents》（工作流五式与&quot;简单优先&quot;）：<a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">https://www.anthropic.com/engineering/building-effective-agents</a></li><li>ReAct（<code>arXiv:2210.03629</code>）、Reflexion（<code>arXiv:2303.11366</code>）；ReAct/规划/反思对照：<a href="https://theaiengineer.substack.com/p/the-4-single-agent-patterns" target="_blank" rel="noreferrer">https://theaiengineer.substack.com/p/the-4-single-agent-patterns</a></li><li>HuggingFace《Design Patterns for Building Agentic Workflows》：<a href="https://huggingface.co/blog/dcarpintero/design-patterns-for-building-agentic-workflows" target="_blank" rel="noreferrer">https://huggingface.co/blog/dcarpintero/design-patterns-for-building-agentic-workflows</a></li><li>Agentic Design Patterns 入门：<a href="https://aman.ai/primers/ai/agentic-design-patterns/" target="_blank" rel="noreferrer">https://aman.ai/primers/ai/agentic-design-patterns/</a></li><li>Microsoft AI Agent Orchestration Patterns；谷歌《Agentic Design Patterns》（xindoo 中文版 21 章）；Augment 2026 Catalog。</li></ul>',4))])}const m=n(c,[["render",A]]);export{_ as __pageData,m as default};
